-- ajoute objets et recettes au Config (appelé à la fin de Config)
function P.apply(C)
	for _, d in P.KINDS do
		C.ITEMS[d.mat] = { name = d.name, icon = d.icon, price = d.price }
		local needs = table.clone(d.needs)
		needs[d.mat] = d.n
		table.insert(C.RECIPES, { gear = d.gear, needs = needs, station = d.station, cat = "equipement", skill = { "artisanat", d.skill } })
		if d.soul then
			C.ITEMS[d.soul.id] = { name = d.soul.name, icon = d.soul.icon, price = d.soul.price }
			table.insert(C.RECIPES, { gear = d.soul.gear, needs = { [d.soul.id] = 1, [d.mat] = 3, gold_ingot = 2 }, station = "anvil", cat = "equipement", skill = { "artisanat", 20 } })
		end
	end
end

return P
